// Generated by `just types` (cli/tests/api_types.rs) from the Rust types luoto's UI API
// sends and takes. Change those, not this file.

export type Access = AccessLevel | string[];

export type AccessLevel =
  /** GET, HEAD, OPTIONS. */
  | "read"
  /** Any method. */
  | "write";

export type AccessRequest = {
  id: number;
  /** Empty for an install request. */
  host: string;
  /** Set for a tunnel request: `access` is then write, since a tunnel's bytes go unread. */
  port?: number;
  access: AccessLevel;
  paths?: string[];
  /** Written by code in the sandbox — untrusted text, display escaped. */
  reason: string;
  status: RequestStatus;
  created: string;
  resolved?: string;
  note?: string;
  /** Software to install instead of access to a host. */
  install?: Install;
};

/** What approving a request did. */
export type Approved =
  /** The rule an access request became. */
  | Rule
  /** What an install request did, for people. */
  | { installed: string };

/** A preset or agent a new env can start with. */
export type Choice = {
  name: string;
  description: string;
};

/** A rule with provenance, as the gate sees it. */
export type CompiledRule = {
  id: string;
  /** `preset:npm`, `user`, `request:3`, `agent:claude`, `provider:anthropic`, `github`. */
  origin: string;
} & Rule;

export type CreatedEnv = {
  ok: boolean;
  name: string;
};

export type Decision = {
  /**
   * When the request shown was filed: the gate numbers requests anew when it restarts, so
   * an id alone could name another request than the one reviewed.
   */
  created: string;
  ttl?: string | null;
  /** Less than the request asked for. */
  narrow?: Narrowing;
  force?: boolean;
};

export type Detection = {
  os: string;
  arch: string;
  distro: string | null;
  cpus: number;
  runtimes: RuntimeInfo[];
  package_manager: string | null;
  wsl: string | null;
};

export type EnvDetail = {
  name: string;
  path: string;
  rules: CompiledRule[];
  injections: Injected[];
  denies: number;
  warnings: string[];
  dev: string;
  gate: string;
  gate_status: GateStatus | null;
  credentials: string[];
  missing_secrets: string[];
  sandbox_secrets: string[];
  ports: EnvPorts;
};

/** Where an env's servers answer on this machine. */
export type EnvPorts = {
  /** Published by the gate (`ports` in the env's config). */
  published: number[];
  /** Forwarded by the watcher. */
  forwarded: number[];
  /** Listened on in the env and not forwarded: the port is taken on this machine. */
  taken: number[];
};

export type EnvRow = {
  name: string;
  dev: string;
  gate: string;
  dir: string | null;
  /** Repositories beside the folder (`repos.rs`). */
  repos: Repo[];
  pending: number;
  denied_recent: number;
  error: string | null;
};

export type EventKind =
  /** A DNS lookup from the sandbox (answered locally, never forwarded). */
  | "dns"
  /** An HTTP request (proxied or intercepted). */
  | "http"
  /** An opaque tunnel (tunnel-mode rule). */
  | "tunnel"
  /** A connection that bypassed the proxy and was caught transparently, non-HTTP. */
  | "direct"
  /** The client rejected our certificate (likely pinning) — suggests a tunnel rule. */
  | "tls_reject"
  /** The sandbox filed an access request. */
  | "request"
  /** An access request was resolved on the host. */
  | "resolve"
  /** The vault issued (or refused) a credential. */
  | "creds"
  /** Start, policy reload, lock/unlock. */
  | "lifecycle";

export type GateStatus = {
  rules: number;
  ca_installed: boolean;
  /**
   * SHA-256 (hex) of the installed CA certificate's PEM text: the host installs the env's
   * CA again when it differs, as after a renewal.
   */
  ca_pem_sha256: string | null;
  vault_configured: boolean;
  pending_requests: number;
};

export type HostSummary = {
  host: string;
  allowed: number;
  denied: number;
  /** Of `denied`, those a mute hides when they are not left out. */
  muted: number;
  dns_only: boolean;
  methods: string[];
  ports: number[];
  intakes: string[];
  top_paths: [string, number][];
  last_reason: string | null;
  last_message: string | null;
  last_rule: string | null;
  bytes_up: number;
  bytes_down: number;
  first_seen: string | null;
  last_seen: string | null;
  wants_write: boolean;
  tls_rejected: boolean;
};

export type Injected = {
  host: string;
  binding: string;
};

/**
 * What the sandbox asks to have in the env besides a host: software, or a preset's access.
 * Approved, it joins the env's config (`[deps] system`, `[tools]`, `presets`), so it holds
 * for every container the env gets.
 */
export type Install =
  /** A package of the image's package manager (apt, apk or dnf). */
  | { kind: "package"; name: string }
  /** A toolchain mise installs: `node` and `24`, `cargo:ripgrep` and `latest`. */
  | { kind: "tool"; name: string; version: string }
  /** One of luoto's presets (`npm`, `pypi`, …): the hosts a registry or service needs. */
  | { kind: "preset"; name: string };

/** What running the recommended install printed. */
export type InstallOutput = {
  ok: boolean;
  command: string;
  output: string;
};

export type Intake = "proxy" | "transparent" | "dns";

export type LuotoEvent = {
  seq: number;
  run: string;
  ts: string | null;
  source: Source | null;
  env: string;
  kind: EventKind | null;
  intake?: Intake;
  verdict?: Verdict;
  method?: string;
  host?: string;
  port?: number;
  path?: string;
  rule?: string;
  /** Machine code (`no_rule`, `method_not_allowed`, …). */
  reason?: string;
  /** Human-readable explanation. */
  message?: string;
  status?: number;
  bytes_up?: number;
  bytes_down?: number;
  ms?: number;
  request_id?: number;
  binding?: string;
};

export type Meta = {
  presets: Choice[];
  agents: Choice[];
};

export type Mode =
  /** TLS is intercepted; method, path, body and credentials are enforced per request. */
  | "inspect"
  /**
   * Opaque TCP tunnel to host:port — for certificate-pinning clients and gRPC. Only the
   * host is enforced.
   */
  | "tunnel";

/**
 * Less than a request asked for, granted by the host: read for write, some methods, some of
 * its paths. Never more: [`AccessRequest::grant`] refuses a narrowing that would widen.
 */
export type Narrowing = {
  /** Read-only (GET, HEAD, OPTIONS). */
  read?: boolean;
  methods?: string[];
  paths?: string[];
};

export type NewEnv = {
  name?: string | null;
  dir?: string | null;
  presets?: string[];
  agents?: string[];
  ports?: number[];
  /** `project_sha` from `detect`: the luoto.toml the user saw, which creating accepts. */
  project_sha?: string | null;
};

export type NewRule = {
  rule: Rule;
  force?: boolean;
};

export type Overview = {
  instance: string;
  /** The watcher shows desktop notifications, so the UI shows none of its own. */
  desktop_notifications: boolean;
  runtime: string;
  envs: EnvRow[];
  vault: VaultStatus | null;
};

export type PlanEntry = {
  path: string;
  /** `new` or `changed`. */
  change: string;
  size: number;
  executable: boolean;
  risky: string | null;
};

export type ProjectAction = {
  /** `accept` the current luoto.toml, or `forget` it. */
  action: string;
  /** The status's `sha`: accept applies only the text the user reviewed. */
  sha?: string | null;
};

/** Where an env stands with its project's luoto.toml. */
export type ProjectState =
  /** The project has no luoto.toml. */
  | "none"
  | "accepted"
  /** It differs from the accepted one. */
  | "changed"
  /** Never accepted. */
  | "new"
  /** This version was ignored. */
  | "declined"
  /** It can't be read or parsed. */
  | "invalid"
  /** The file is gone; the accepted settings still apply. */
  | "removed";

export type ProjectStatus = {
  state: ProjectState;
  accepted: [string, string][];
  current: [string, string][];
  /** What applying the current text adds (`+`) and removes (`-`). */
  diff: string[];
  error: string | null;
  /** Config snippets for credentials the project needs and the env lacks. */
  needs: string[];
  /** `sha` of the current text; accepting it in the UI must name this. */
  sha: string | null;
};

/** What creating an env from these choices would produce. */
export type Proposal = {
  name: string;
  /** The folder is missing (created with the env) or empty: nothing to detect. */
  new_folder: boolean;
  presets: ProposedPreset[];
  tools: ToolPin[];
  /** The folder's luoto.toml as `[label, value]` lines; creating the env accepts it. */
  project: [string, string][] | null;
  /** sha256 of that luoto.toml: creating the env names it, so only this text is accepted. */
  project_sha: string | null;
  project_error: string | null;
};

export type ProposedPreset = {
  name: string;
  /** The file that suggested it; `None` for a preset every env starts with. */
  reason: string | null;
};

export type PullApply = {
  digest: string;
  include_risky?: boolean;
};

export type PullPlan = {
  dir: string;
  /** The repo it pulls, or `None` for the workspace. */
  repo: string | null;
  entries: PlanEntry[];
  unchanged: number;
  /** Entries refused outright (unsafe paths, links leaving the folder, special files). */
  refused: [string, string][];
  /**
   * Hash over what would be written; applying re-checks it so a sandbox can't swap files
   * between your review and the write.
   */
  digest: string;
};

/** Every folder a pull writes, and one digest over them that applying checks. */
export type PullPlans = {
  plans: PullPlan[];
  digest: string;
};

export type Pulled = {
  written: number;
  skipped: number;
};

export type Recommendation = {
  summary: string;
  reasons: string[];
  /** Shell command to install (shown first; run only on confirmation). */
  install: string[] | null;
  notes: string[];
};

/** What [`reload`] did. */
export type Reloaded = {
  read: number;
  changed: number;
  /** The references that couldn't be read, and the gates that weren't flushed. */
  failed: string[];
};

export type Repo = {
  name: string;
  /** The host folder or the remote. */
  source: string;
  /** `folder` (copied in) or `clone`. */
  kind: string;
  branch: string | null;
  origin: RepoOrigin;
  /** In the workspace already (copied, cloned or found there). */
  present: boolean;
};

/** Where a repo came from, for listings. */
export type RepoOrigin = "env" | "project";

export type RequestStatus = "pending" | "approved" | "rejected";

/** One allow rule. `port: None` means the standard ports 80 and 443. */
export type Rule = {
  /** Stable id for user rules in env configs (presets leave it empty). */
  id?: string;
  host: string;
  port?: number;
  access: Access;
  paths?: string[];
  expires?: string;
  mode?: Mode;
  /** Permit `Upgrade: websocket` (a full-duplex channel even under read access). */
  ws?: boolean;
  /** Cap on request body bytes (used for read-POST endpoints like git-upload-pack). */
  max_body?: number;
  /** Allow dialing private/loopback/host-gateway addresses for this host. */
  allow_private?: boolean;
  /** Free-text note shown in the UI. */
  note?: string;
  /**
   * Match `paths` without regard to ASCII case, for hosts whose paths are case-insensitive
   * (Azure DevOps organizations, projects and repositories).
   */
  ignore_case?: boolean;
  /**
   * How long the host may stay silent (`30m`, `2h`) before the gate closes the connection,
   * in place of its default: for long polls such as `kubectl logs -f`.
   */
  idle?: string;
};

